import { Mesh, PlaneGeometry, Vector3, Euler, DoubleSide } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{ imageUrl?: string, depthMapUrl?: string, meshUrl?: string }} assets
 * @property {{ position: [number, number, number], rotation: [number, number, number], scale: [number, number, number] }} scenePlacement
 * @property {Array<{ name: string, params: any }>} cinematicPrimitives
 * @property {Array<any>} interactions
 * @property {any} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {{ load: (url:string)=>any }} textureLoader
 * @property {{ load: (url:string)=>any }} glbLoader
 * @property {{ [key:string]: Function }} primitives
 * @property {{ fontAtlas: any }} fontAtlas
 */

/**
 * Creates a textured plane badge node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
    // Geometry
    const geometry = new PlaneGeometry(1, 1);

    // Texture
    let map = null;
    if (config.assets && config.assets.imageUrl) {
        map = ctx.textureLoader.load(config.assets.imageUrl);
    }

    // Material (basic, no lighting required)
    const material = new MeshBasicNodeMaterial({
        map,
        side: DoubleSide,
        transparent: true,
        toneMapped: false,
    });

    // Mesh
    const mesh = new Mesh(geometry, material);
    mesh.name = 'badge-pricing';

    // Placement
    const [px, py, pz] = config.scenePlacement?.position ?? [0, 0, 0];
    const [rx, ry, rz] = config.scenePlacement?.rotation ?? [0, 0, 0];
    const [sx, sy, sz] = config.scenePlacement?.scale ?? [1, 1, 1];

    mesh.position.set(px, py, pz);
    mesh.rotation.set(rx, ry, rz);
    mesh.scale.set(sx, sy, sz);

    // Apply cinematic primitives if any
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const primitive of config.cinematicPrimitives) {
            const fn = ctx.primitives[primitive.name];
            if (typeof fn === 'function') {
                fn(mesh, primitive.params);
            }
        }
    }

    // Interaction handlers
    mesh.userData.handlers = {};

    // Hover rise‑in (subtle 0.15 scene units)
    const riseDistance = 0.15;
    let hoverTween = null;

    function onHoverEnter() {
        if (hoverTween) hoverTween.kill();
        hoverTween = gsap.to(mesh.position, {
            y: mesh.position.y + riseDistance,
            duration: 0.7,
            ease: 'power3.out',
        });
    }

    function onHoverLeave() {
        if (hoverTween) hoverTween.kill();
        hoverTween = gsap.to(mesh.position, {
            y: mesh.position.y - riseDistance,
            duration: 0.7,
            ease: 'power3.out',
        });
    }

    mesh.userData.handlers.hoverEnter = onHoverEnter;
    mesh.userData.handlers.hoverLeave = onHoverLeave;

    // Click emit
    mesh.userData.handlers.click = () => {
        // The surrounding system can interpret the returned payload.
        return { type: 'hub-pricing.select' };
    };

    // Cleanup
    mesh.userData.cleanup = () => {
        if (hoverTween) hoverTween.kill();
        geometry.dispose();
        material.dispose();
        if (map && typeof map.dispose === 'function') {
            map.dispose();
        }
    };

    return mesh;
}
